func (patch parameterValidationPatch) Apply(_ context.Context, result *client.WAFModuleResult) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if result == nil {
		diagnostics.AddError("Unable to merge parameter validation configuration", "The current API result was nil.")
		return diagnostics
	}
	set := func(name string, value any) {
		if err := result.SetConfig(name, value); err != nil {
			diagnostics.AddError("Unable to merge parameter validation configuration", fmt.Sprintf("Unable to encode %s: %v", name, err))
		}
	}
	if patch.Status.Set {
		set("status", patch.Status.Value)
	}

	if patch.RuleList.Set {
		// Merge preserved nested sub-item arrays / item string-arrays from the
		// fresh GET into a per-attempt clone of the patch items. This ensures
		// opaque preservation (the PUT carries the fresh GET's nested raw
		// value, including unknown keys and null) and is safe across 409
		// retries (the original patch is not mutated; the clone is rebuilt
		// from each fresh GET).
		ruleListGetRaw := result.Configs["rule_list"]
		ruleListPatchItems := make([]parameterValidationRuleListWireItem, len(patch.RuleList.Items))
		copy(ruleListPatchItems, patch.RuleList.Items)
		if len(ruleListGetRaw) > 0 && !parameterValidationJSONNull(ruleListGetRaw) {
			var ruleListGetItems []map[string]json.RawMessage
			if err := json.Unmarshal(ruleListGetRaw, &ruleListGetItems); err == nil {
				// Preserve omitted nested arrays by matching each patch item to a
				// unique unconsumed fresh-GET item by its "unchanged projection"
				// (canonical content of every known parent field except the
				// wire-only idx and the nested ownership fields). There is no
				// proven stable identity field (idx is regenerated sequentially;
				// cat/name are not unique), so preservation matches by unchanged
				// content, not identity. A unique unconsumed match is required:
				// a changed, new, reordered-differently, or duplicate item with
				// an omitted nested wrapper cannot be matched safely, so the
				// apply is refused (omission means preserve; an ambiguous mapping
				// must fail rather than be guessed). One remote item cannot
				// satisfy two patch items (consumed map).
				ruleListConsumed := make(map[int]bool, len(ruleListGetItems))
				for i := range ruleListPatchItems {
					// Determine whether any nested ownership field is omitted for
					// this patch item; only then is preservation needed.
					ruleListOmitAny := false
					if len(ruleListPatchItems[i].SubRuleList) == 0 {
						ruleListOmitAny = true
					}
					if ruleListOmitAny && len(ruleListGetItems) > 0 {
						// Only preserve when the fresh GET has existing items to
						// preserve from. When the remote collection is empty,
						// every patch item is new: an omitted nested wrapper has
						// nothing to preserve and stays omitted (no refusal).
						match, matchIndex, ok := parameterValidationRuleListMatchGetItem(ruleListPatchItems[i], ruleListGetItems, ruleListConsumed)
						if !ok {
							diagnostics.AddError("Cannot preserve omitted nested array",
								fmt.Sprintf("configs.rule_list.item[%d] omits a nested ownership wrapper, but the provider could not uniquely match the parent item to the fresh GET by its unchanged content. Apply was refused because omission means preserve. Configure each omitted wrapper explicitly: an empty wrapper sends []; a populated wrapper replaces the array.", i+1))
							return diagnostics
						}
						ruleListConsumed[matchIndex] = true
						if len(ruleListPatchItems[i].SubRuleList) == 0 {
							if subRaw, ok := match["sub_rule_list"]; ok && len(subRaw) > 0 {
								ruleListPatchItems[i].SubRuleList = subRaw
							}
						}
					}
				}
			}
		}
		set("rule_list", ruleListPatchItems)
	}
	return diagnostics
}

func parameterValidationValidateConfiguredRuleList(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var value parameterValidationWrapperModel
	diagnostics.Append(wrapper.As(ctx, &value, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || value.Items.IsNull() || value.Items.IsUnknown() {
		return diagnostics
	}
	if len(value.Items.Elements()) > parameterValidationRuleListMaxItems {
		diagnostics.AddError("Invalid parameter validation rule_list", fmt.Sprintf("rule_list may contain at most %d item blocks.", parameterValidationRuleListMaxItems))
		return diagnostics
	}
	var items []parameterValidationRuleListItemModel
	diagnostics.Append(value.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("rule_list item %d", index+1)
		if item.Action.IsNull() {
			diagnostics.AddError("Invalid parameter validation item", location+" action is required.")
		} else if !item.Action.IsUnknown() {
			parameterValidationValidateString(location, " action", item.Action.ValueString(), 0, 0, &diagnostics)
			if !parameterValidationRuleListActionValid(item.Action.ValueString()) {
				diagnostics.AddError("Invalid parameter validation item", location+" action must be one of alert, alert_deny, block_period, deny_no_log.")
			}
		}
		if item.Name.IsNull() {
			diagnostics.AddError("Invalid parameter validation item", location+" name is required.")
		} else if !item.Name.IsUnknown() {
			parameterValidationValidateString(location, " name", item.Name.ValueString(), 0, 49, &diagnostics)
		}
		if item.URL.IsNull() {
			diagnostics.AddError("Invalid parameter validation item", location+" url is required.")
		} else if !item.URL.IsUnknown() {
			parameterValidationValidateString(location, " url", item.URL.ValueString(), 0, 2071, &diagnostics)
			parameterValidationValidatePattern(location, " url", item.URL.ValueString(), parameterValidationRuleListURLPattern, "must begin with /", &diagnostics)
		}
	}
	return diagnostics
}

func parameterValidationBuildConfiguredRuleList(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (parameterValidationRuleListOwnedList, diag.Diagnostics) {
	if configured.IsNull() {
		return parameterValidationRuleListOwnedList{}, diagnostics
	}
	if configured.IsUnknown() {
		diagnostics.AddError("Unknown parameter validation rule_list", "The rule_list ownership wrapper must be known during apply.")
		return parameterValidationRuleListOwnedList{}, diagnostics
	}
	if planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown parameter validation rule_list", "The planned rule_list ownership wrapper must be known during apply.")
		return parameterValidationRuleListOwnedList{}, diagnostics
	}
	var configWrapper, planWrapper parameterValidationWrapperModel
	diagnostics.Append(configured.As(ctx, &configWrapper, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planWrapper, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return parameterValidationRuleListOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsUnknown() || planWrapper.Items.IsUnknown() {
		diagnostics.AddError("Unknown parameter validation rule_list", "The rule_list item blocks must be known during apply.")
		return parameterValidationRuleListOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsNull() {
		return parameterValidationRuleListOwnedList{Set: true, Items: []parameterValidationRuleListWireItem{}}, diagnostics
	}

	var configItems, planItems []parameterValidationRuleListItemModel
	diagnostics.Append(configWrapper.Items.ElementsAs(ctx, &configItems, false)...)
	if planWrapper.Items.IsNull() {
		if len(configItems) != 0 {
			diagnostics.AddError("Invalid parameter validation rule_list", "The planned item list unexpectedly became null.")
		}
		return parameterValidationRuleListOwnedList{Set: true, Items: []parameterValidationRuleListWireItem{}}, diagnostics
	}
	diagnostics.Append(planWrapper.Items.ElementsAs(ctx, &planItems, false)...)
	if diagnostics.HasError() {
		return parameterValidationRuleListOwnedList{}, diagnostics
	}
	if len(configItems) != len(planItems) {
		diagnostics.AddError("Invalid parameter validation rule_list", "Configured and planned item counts differ.")
		return parameterValidationRuleListOwnedList{}, diagnostics
	}
	if len(configItems) > parameterValidationRuleListMaxItems {
		diagnostics.AddError("Invalid parameter validation rule_list", fmt.Sprintf("rule_list may contain at most %d item blocks.", parameterValidationRuleListMaxItems))
		return parameterValidationRuleListOwnedList{}, diagnostics
	}

	items := make([]parameterValidationRuleListWireItem, 0, len(configItems))
	for index := range configItems {
		configuredItem := configItems[index]
		plannedItem := planItems[index]
		location := fmt.Sprintf("rule_list item %d", index+1)
		item := parameterValidationRuleListWireItem{
			Index: index + 1,
		}
		actionValue, ok := parameterValidationPlannedRequiredString(configuredItem.Action, plannedItem.Action, location+" action", &diagnostics)
		if !ok {
			continue
		}
		parameterValidationValidateString(location, " action", actionValue, 0, 0, &diagnostics)
		if !parameterValidationRuleListActionValid(actionValue) {
			diagnostics.AddError("Invalid parameter validation item", location+" action must be one of alert, alert_deny, block_period, deny_no_log.")
		}
		item.Action = actionValue
		item.BlockPeriod = parameterValidationPlannedOptionalInt64(configuredItem.BlockPeriod, plannedItem.BlockPeriod, location+" block_period", 60, &diagnostics)
		if !configuredItem.BlockPeriod.IsNull() && !configuredItem.BlockPeriod.IsUnknown() && (item.BlockPeriod < 1 || item.BlockPeriod > 3600) {
			diagnostics.AddError("Invalid parameter validation item", fmt.Sprintf("%s block_period must be between 1 and 3600.", location))
		}
		nameValue, ok := parameterValidationPlannedRequiredString(configuredItem.Name, plannedItem.Name, location+" name", &diagnostics)
		if !ok {
			continue
		}
		parameterValidationValidateString(location, " name", nameValue, 0, 49, &diagnostics)
		item.Name = nameValue

		sub_rule_listBuilt := parameterValidationRuleListBuildNestedSubRuleList(ctx, configuredItem.SubRuleList, plannedItem.SubRuleList, location, &diagnostics)
		if sub_rule_listBuilt != nil {
			item.SubRuleList, _ = json.Marshal(sub_rule_listBuilt)
		}
		urlValue, ok := parameterValidationPlannedRequiredString(configuredItem.URL, plannedItem.URL, location+" url", &diagnostics)
		if !ok {
			continue
		}
		parameterValidationValidateString(location, " url", urlValue, 0, 2071, &diagnostics)
		parameterValidationValidatePattern(location, " url", urlValue, parameterValidationRuleListURLPattern, "must begin with /", &diagnostics)
		item.URL = urlValue
		items = append(items, item)
	}
	return parameterValidationRuleListOwnedList{Set: true, Items: items}, diagnostics
}

